export class UtilsCodeServerService {
    /**
     * 获取code-server的token并且启动容器
     * 获取 code-server 认证令牌，并确保用户容器已启动。
     *
     * 流程：
     * 1. 生成 code 作用域的 JWT 令牌并设置为 httponly cookie
     * 2. 确保用户工作空间目录和配置文件存在
     * 3. 检查并启动 code-server Docker 容器
     * 4. 若容器是新启动的，异步等待服务就绪日志后再返回
     * @param data The data for the request.
     * @param data.dark True for dark theme, False for light theme
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static getCodeToken(data: UtilsCodeServerGetCodeTokenData = {}): CancelablePromise<UtilsCodeServerGetCodeTokenResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/utils/get_code_token',
            query: {
                dark: data.dark
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
}

